  [467882] = { "Mentre Folgore Statica è incisa, il tuo ⟦Lightning Shield=Scudo di Fulmini⟧ ottiene una carica ogni volta che colpisci un bersaglio con ⟦Lightning Bolt=Dardo Fulminante⟧ o ⟦Chain Lightning=Catena di Fulmini⟧, fino a un massimo di $N1 cariche. Inoltre, mentre Folgore Statica è incisa, il tuo ⟦Lightning Shield=Scudo di Fulmini⟧ può infliggere danni critici.", nil, 0x123b9f53, nil, "um" },
  [467889] = { "La tua ⟦Flame Shock=Folgore del Fuoco⟧ aumenta anche del $N1% la probabilità di blocco per $D1 o finché non blocchi un attacco.", nil, 0x0091b642, nil, "um" },
  [467891] = { nil, "Probabilità di blocco aumentata del $N1% per il prossimo attacco.", nil, 0x5e5aa2c3, "mu" },
  [467909] = { "Ogni volta che blocchi, il valore di blocco aumenta del $N1% dei tuoi danni magici per $D1, effetto che si accumula fino a $N3 volte.", nil, 0x388b874e, nil, "um" },
  [467910] = { nil, "Valore di blocco aumentato di $N1.", nil, 0x5ac40f68, "mu" },
  [467916] = { "Ogni volta che blocchi un attacco, hai una probabilità del $N1% di attivare la tua runa Arma del Maelstrom.", nil, 0x27839c75, nil, "um" },
  [467917] = { "Aumenta del $N1% i danni dei tuoi incantesimi periodici e della tua vilguardia.", nil, 0x9402b716, nil, "um" },
  [467983] = { "I danni periodici dei tuoi incantesimi Ombrofuoco, Afflizione Instabile e ⟦Curse of Agony=Maledizione dell'Agonia⟧ e i danni inflitti dalla tua vilguardia hanno una probabilità del $N1% di conferire l'effetto Shadow Trance.", nil, 0xee71af0d, nil, "um" },
  [467988] = { "Dardo d'Ombra infligge il $N1% di danni in più per ogni tuo effetto che affligge il bersaglio, fino a un massimo del $N2%.", nil, 0x5ce67215, nil, "um" },
})
